INSERT INTO curated_examples (id, data) VALUES ('research', '{"species":[{"id":"example-ipomoea-violacea","scientificName":"Ipomoea violacea","acceptedName":"","commonNames":[],"synonyms":[],"group":"plant","genus":"Ipomoea","family":"Convolvulaceae","taxonomy":{},"description":"","diagnostics":"","distribution":"","habitat":"","toxicity":"","traditionalUses":"","notes":"Nome historicamente aplicado por engano a I. tricolor. A fonte taxonômica não atribui propriedades alucinógenas à verdadeira I. violacea; não extrapolar dados de I. tricolor.","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-casearia-sylvestris","scientificName":"Casearia sylvestris","acceptedName":"","commonNames":[],"synonyms":[],"group":"plant","genus":"Casearia","family":"Salicaceae","taxonomy":{},"description":"","diagnostics":"","distribution":"","habitat":"","toxicity":"","traditionalUses":"","notes":"Cafezeiro-do-mato segundo a Embrapa; o nome popular pode variar por região.","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-mimosa-scabrella","scientificName":"Mimosa scabrella","acceptedName":"","commonNames":[],"synonyms":[],"group":"plant","genus":"Mimosa","family":"Fabaceae","taxonomy":{},"description":"","diagnostics":"","distribution":"","habitat":"","toxicity":"","traditionalUses":"","notes":"O artigo de 1990 relata alcaloides na casca analisada, e outro estudo isolou galactomanana das sementes. Isso não determina o teor de uma árvore observada em campo.","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-amanita-muscaria","scientificName":"Amanita muscaria","acceptedName":"","commonNames":[],"synonyms":[],"group":"fungus","genus":"Amanita","family":"Amanitaceae","taxonomy":{},"description":"","diagnostics":"","distribution":"","habitat":"","toxicity":"","traditionalUses":"","notes":"Fungo tóxico. Estudos com muscimol isolado não demonstram segurança nem efeito equivalente ao consumir o cogumelo.","createdAt":"2026-09-24T00:00:00.000Z"}],"compounds":[{"id":"example-casearin-x","name":"casearin X","synonyms":[],"chemicalClass":"Diterpeno clerodano","formula":"","description":"","mechanisms":"","targets":"","effects":"","effectClaims":[{"id":"example-casearin-x-cytotoxicity","kind":"other","context":"isolated_compound","type":"in_vitro","claim":"Casearin X isolada apresentou citotoxicidade em linhagens celulares humanas em laboratório; não é evidência de tratamento clínico.","source":"Santos et al., Chemistry & Biodiversity (2010)","url":"https://pubmed.ncbi.nlm.nih.gov/20087991/","createdAt":"2026-09-24T00:00:00.000Z"}],"toxicology":"","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-galactomannan","name":"galactomanana","synonyms":[],"chemicalClass":"Polissacarídeo","formula":"","description":"","mechanisms":"","targets":"","effects":"","effectClaims":[],"toxicology":"","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-dmt","name":"N,N-dimetiltriptamina (DMT)","synonyms":[],"chemicalClass":"Triptamina","formula":"","description":"","mechanisms":"","targets":"","effects":"","effectClaims":[{"id":"example-dmt-psychedelic","kind":"psychedelic","context":"isolated_compound","type":"human","claim":"Um estudo controlado observou efeitos psicodélicos com DMT isolada administrada por via intravenosa em participantes humanos; não estudou a casca de bracatinga nem seu consumo.","source":"Estudo clínico com DMT isolada (2023)","url":"https://pubmed.ncbi.nlm.nih.gov/37221177/","createdAt":"2026-09-24T00:00:00.000Z"}],"toxicology":"","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-muscimol","name":"muscimol","synonyms":[],"chemicalClass":"Isoxazol","formula":"","description":"","mechanisms":"","targets":"","effects":"","effectClaims":[{"id":"example-muscimol-sedation","kind":"sedative","context":"isolated_compound","type":"animal","claim":"Muscimol administrado diretamente a uma região cerebral produziu sedação em ratos; isso não descreve o efeito da ingestão de Amanita muscaria.","source":"Nelson et al., Nature Neuroscience (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/12195434/","createdAt":"2026-09-24T00:00:00.000Z"}],"toxicology":"","createdAt":"2026-09-24T00:00:00.000Z"}],"evidence":[{"id":"example-casearin-x-leaves","speciesId":"example-casearia-sylvestris","compoundId":"example-casearin-x","property":"composição química","claim":"Casearin X foi isolada de extrato etanólico das folhas de Casearia sylvestris.","type":"publication","origin":"publication","source":"Santos et al., Chemistry & Biodiversity (2010)","url":"https://pubmed.ncbi.nlm.nih.gov/20087991/","part":"Folhas","concentration":"","unit":"","range":"","method":"","sampleOrigin":"","notes":"","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-galactomannan-seeds","speciesId":"example-mimosa-scabrella","compoundId":"example-galactomannan","property":"composição química","claim":"O estudo isolou galactomanana das sementes de Mimosa scabrella; não relatou efeito neuroativo.","type":"publication","origin":"publication","source":"Ganter et al., International Journal of Biological Macromolecules (1997)","url":"https://pubmed.ncbi.nlm.nih.gov/9283028/","part":"Sementes","concentration":"","unit":"","range":"","method":"","sampleOrigin":"","notes":"","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-dmt-bark","speciesId":"example-mimosa-scabrella","compoundId":"example-dmt","property":"composição química","claim":"Moraes e colaboradores identificaram N,N-dimetiltriptamina em extrato alcoólico da casca de Mimosa scabrella.","type":"publication","origin":"publication","source":"Moraes et al., Química Nova (1990)","url":"https://quimicanova.sbq.org.br/Content/pdf/Vol13No4_308_v13_n4_(21).pdf","part":"Casca","concentration":"","unit":"","range":"","method":"","sampleOrigin":"","notes":"Relato fitoquímico de material estudado; não quantifica uma amostra encontrada em campo.","createdAt":"2026-09-24T00:00:00.000Z"},{"id":"example-muscimol-fruiting-body","speciesId":"example-amanita-muscaria","compoundId":"example-muscimol","property":"composição química","claim":"O estudo identificou muscimol e ácido ibotênico em exemplares de Amanita muscaria analisados.","type":"publication","origin":"publication","source":"Poliwoda et al., Electrophoresis (2014)","url":"https://pubmed.ncbi.nlm.nih.gov/24981810/","part":"Corpo de frutificação","concentration":"","unit":"","range":"","method":"","sampleOrigin":"","notes":"","createdAt":"2026-09-24T00:00:00.000Z"}]}') ON CONFLICT(id) DO NOTHING;
